import React, { useState } from 'react';
import toast from 'react-hot-toast';
import { downloadPartywiseExcel, triggerDownload } from '../services/api';
import { ChevronDown, ChevronRight, CheckCircle, Download, Mail } from 'lucide-react';

export default function MatchedResults({ results, sendResult }) {
  const [expanded, setExpanded] = useState({});
  const [downloading, setDownloading] = useState(false);

  const toggle = (code) => setExpanded(p => ({ ...p, [code]: !p[code] }));

  const handleDownload = async () => {
    setDownloading(true);
    try {
      const res = await downloadPartywiseExcel();
      triggerDownload(res.data, `All_Partywise_Payments_${new Date().toISOString().slice(0,10)}.xlsx`);
    } catch {
      toast.error('Download failed');
    } finally {
      setDownloading(false);
    }
  };

  const getStatus = (partyCode) => {
    if (!sendResult?.results) return null;
    return sendResult.results.find(r => r.partyCode === partyCode);
  };

  return (
    <div className="matched-results">
      <div className="matched-header">
        <span className="badge badge-green">{results.length} parties ready</span>
        <button className="btn btn-secondary" onClick={handleDownload} disabled={downloading}>
          {downloading ? <span className="spinner-sm" /> : <Download size={16} />}
          Download All Party-wise Excel
        </button>
      </div>

      <div className="party-list">
        {results.map((entry, i) => {
          const isOpen = expanded[entry.partyCode];
          const status = getStatus(entry.partyCode);

          return (
            <div key={i} className={`party-card ${status?.status === 'sent' ? 'sent' : status?.status === 'failed' ? 'failed' : ''}`}>
              <div className="party-card-header" onClick={() => toggle(entry.partyCode)}>
                <div className="party-card-left">
                  {isOpen ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                  <span className="party-name">{entry.partyCode}</span>
                  <span className="party-meta">
                    <Mail size={12} /> {entry.emails.join(', ')}
                  </span>
                  <span className="party-meta">{entry.payments.length} invoices</span>
                </div>
                <div className="party-card-right">
                  {status?.status === 'sent' && <span className="badge badge-green"><CheckCircle size={12} /> Sent</span>}
                  {status?.status === 'failed' && <span className="badge badge-red">✗ Failed</span>}
                </div>
              </div>

              {isOpen && (
                <div className="party-card-body">
                  {/* CC emails */}
                  {entry.ccEmails?.length > 0 && (
                    <p className="cc-line"><strong>CC:</strong> {entry.ccEmails.join(', ')}</p>
                  )}

                  {/* Payment rows table */}
                  <div className="table-wrap">
                    <table>
                      <thead>
                        <tr>
                          <th>Inv. No.</th>
                          <th>Main Advised No.</th>
                          <th>Seller Advised No.</th>
                          <th>Transaction Type</th>
                          <th>Purchase Date</th>
                          <th>Total Amt</th>
                          <th>Debit</th>
                          <th>Bank Payment</th>
                        </tr>
                      </thead>
                      <tbody>
                        {entry.payments.map((p, j) => (
                          <tr key={j}>
                            <td>{p['Inv. No.'] || '-'}</td>
                            <td>{p['Main Advised No.'] || '-'}</td>
                            <td>{p['Seller Advised No.'] || '-'}</td>
                            <td>{p['Transaction Type'] || '-'}</td>
                            <td>{p['Pur. Date'] ? new Date(p['Pur. Date']).toLocaleDateString('en-IN') : '-'}</td>
                            <td>{p['Total Inv. Amount'] != null ? Number(p['Total Inv. Amount']).toFixed(2) : '-'}</td>
                            <td>{p['Debit Amount'] > 0 ? Number(p['Debit Amount']).toFixed(2) : '-'}</td>
                            <td>{p['Bank Payment'] > 0 ? Number(p['Bank Payment']).toFixed(2) : '-'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>

                  {/* Debit notes */}
                  {entry.debits?.length > 0 && (
                    <>
                      <h4 className="subtable-title">Debit Notes</h4>
                      <div className="table-wrap">
                        <table>
                          <thead>
                            <tr>
                              <th>Return Invoice No.</th>
                              <th>Date</th>
                              <th>Amount</th>
                            </tr>
                          </thead>
                          <tbody>
                            {entry.debits.map((d, j) => (
                              <tr key={j}>
                                <td>{d['Return Invoice No.'] || '-'}</td>
                                <td>{d['Date'] ? new Date(d['Date']).toLocaleDateString('en-IN') : '-'}</td>
                                <td>{Number(d['Amount']).toFixed(2)}</td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    </>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}
